    77→// Action represents a side effect that should be performed after a transition.
    78→// The caller is responsible for executing these -- the state machine only declares them.
    79→type Action int
    80→
    81→const (
    82→	ActionCondense               Action = iota // Condense session data to permanent storage
    83→	ActionCondenseIfFilesTouched               // Condense only if FilesTouched is non-empty
    84→	ActionDiscardIfNoFiles                     // Discard session if FilesTouched is empty
    85→	ActionMigrateShadowBranch                  // Migrate shadow branch to new HEAD
    86→	ActionWarnStaleSession                     // Warn user about stale session(s)
    87→	ActionClearEndedAt                         // Clear EndedAt timestamp (session re-entering)
    88→	ActionUpdateLastInteraction                // Update LastInteractionTime
    89→)
    90→
    91→// String returns a human-readable name for the action.
    92→func (a Action) String() string {
    93→	switch a {
    94→	case ActionCondense:
    95→		return "Condense"
    96→	case ActionCondenseIfFilesTouched:
    97→		return "CondenseIfFilesTouched"
    98→	case ActionDiscardIfNoFiles:
    99→		return "DiscardIfNoFiles"
   100→	case ActionMigrateShadowBranch:
   101→		return "MigrateShadowBranch"
   102→	case ActionWarnStaleSession:
   103→		return "WarnStaleSession"
   104→	case ActionClearEndedAt:
   105→		return "ClearEndedAt"
   106→	case ActionUpdateLastInteraction:
   107→		return "UpdateLastInteraction"
   108→	default:
   109→		return fmt.Sprintf("Action(%d)", int(a))
   110→	}
   111→}
