   113→// TransitionContext provides read-only context for transitions that need
   114→// to inspect session state without mutating it.
   115→type TransitionContext struct {
   116→	HasFilesTouched    bool // len(FilesTouched) > 0
   117→	IsRebaseInProgress bool // .git/rebase-merge/ or .git/rebase-apply/ exists
   118→}
   119→
   120→// TransitionResult holds the outcome of a state machine transition.
   121→type TransitionResult struct {
   122→	NewPhase Phase
   123→	Actions  []Action
   124→}
   125→
   126→// Transition computes the next phase and required actions given the current
   127→// phase and an event. This is a pure function with no side effects.
   128→//
   129→// Empty or unknown phase values are normalized to PhaseIdle for backward
   130→// compatibility with session state files created before phase tracking.
   131→func Transition(current Phase, event Event, ctx TransitionContext) TransitionResult {
   132→	// Normalize empty/unknown phase to idle for backward compatibility.
   133→	current = PhaseFromString(string(current))
   134→
   135→	switch current {
   136→	case PhaseIdle:
   137→		return transitionFromIdle(event, ctx)
   138→	case PhaseActive:
   139→		return transitionFromActive(event, ctx)
   140→	case PhaseActiveCommitted:
   141→		return transitionFromActiveCommitted(event, ctx)
   142→	case PhaseEnded:
   143→		return transitionFromEnded(event, ctx)
   144→	default:
   145→		// PhaseFromString guarantees we only get known phases, but the
   146→		// exhaustive linter requires handling the default case.
   147→		return TransitionResult{NewPhase: PhaseIdle}
   148→	}
   149→}
   150→
   151→func transitionFromIdle(event Event, ctx TransitionContext) TransitionResult {
   152→	switch event {
   153→	case EventTurnStart:
   154→		return TransitionResult{
   155→			NewPhase: PhaseActive,
   156→			Actions:  []Action{ActionUpdateLastInteraction},
   157→		}
   158→	case EventTurnEnd:
   159→		// Turn end while idle is a no-op (no active turn to end).
   160→		return TransitionResult{NewPhase: PhaseIdle}
   161→	case EventGitCommit:
   162→		if ctx.IsRebaseInProgress {
   163→			return TransitionResult{NewPhase: PhaseIdle}
   164→		}
   165→		return TransitionResult{
   166→			NewPhase: PhaseIdle,
   167→			Actions:  []Action{ActionCondense, ActionUpdateLastInteraction},
   168→		}
   169→	case EventSessionStart:
   170→		// Already condensable, no-op.
   171→		return TransitionResult{NewPhase: PhaseIdle}
   172→	case EventSessionStop:
   173→		return TransitionResult{
   174→			NewPhase: PhaseEnded,
   175→			Actions:  []Action{ActionUpdateLastInteraction},
   176→		}
   177→	default:
   178→		return TransitionResult{NewPhase: PhaseIdle}
   179→	}
   180→}
   181→
   182→func transitionFromActive(event Event, ctx TransitionContext) TransitionResult {
   183→	switch event {
   184→	case EventTurnStart:
   185→		// Ctrl-C recovery: just continue.
   186→		return TransitionResult{
   187→			NewPhase: PhaseActive,
   188→			Actions:  []Action{ActionUpdateLastInteraction},
   189→		}
   190→	case EventTurnEnd:
   191→		return TransitionResult{
   192→			NewPhase: PhaseIdle,
   193→			Actions:  []Action{ActionUpdateLastInteraction},
   194→		}
   195→	case EventGitCommit:
   196→		if ctx.IsRebaseInProgress {
   197→			return TransitionResult{NewPhase: PhaseActive}
   198→		}
   199→		return TransitionResult{
   200→			NewPhase: PhaseActiveCommitted,
   201→			Actions:  []Action{ActionMigrateShadowBranch, ActionUpdateLastInteraction},
   202→		}
   203→	case EventSessionStart:
   204→		return TransitionResult{
   205→			NewPhase: PhaseActive,
   206→			Actions:  []Action{ActionWarnStaleSession},
   207→		}
   208→	case EventSessionStop:
   209→		return TransitionResult{
   210→			NewPhase: PhaseEnded,
   211→			Actions:  []Action{ActionUpdateLastInteraction},
   212→		}
   213→	default:
   214→		return TransitionResult{NewPhase: PhaseActive}
   215→	}
   216→}
   217→
   218→func transitionFromActiveCommitted(event Event, ctx TransitionContext) TransitionResult {
   219→	switch event {
   220→	case EventTurnStart:
   221→		// Ctrl-C recovery after commit.
   222→		return TransitionResult{
   223→			NewPhase: PhaseActive,
   224→			Actions:  []Action{ActionUpdateLastInteraction},
   225→		}
   226→	case EventTurnEnd:
   227→		return TransitionResult{
   228→			NewPhase: PhaseIdle,
   229→			Actions:  []Action{ActionCondense, ActionUpdateLastInteraction},
   230→		}
   231→	case EventGitCommit:
   232→		if ctx.IsRebaseInProgress {
   233→			return TransitionResult{NewPhase: PhaseActiveCommitted}
   234→		}
   235→		return TransitionResult{
   236→			NewPhase: PhaseActiveCommitted,
   237→			Actions:  []Action{ActionMigrateShadowBranch, ActionUpdateLastInteraction},
   238→		}
   239→	case EventSessionStart:
   240→		return TransitionResult{
   241→			NewPhase: PhaseActiveCommitted,
   242→			Actions:  []Action{ActionWarnStaleSession},
   243→		}
   244→	case EventSessionStop:
   245→		return TransitionResult{
   246→			NewPhase: PhaseEnded,
   247→			Actions:  []Action{ActionUpdateLastInteraction},
   248→		}
   249→	default:
   250→		return TransitionResult{NewPhase: PhaseActiveCommitted}
   251→	}
   252→}
   253→
   254→func transitionFromEnded(event Event, ctx TransitionContext) TransitionResult {
   255→	switch event {
   256→	case EventTurnStart:
   257→		return TransitionResult{
   258→			NewPhase: PhaseActive,
   259→			Actions:  []Action{ActionClearEndedAt, ActionUpdateLastInteraction},
   260→		}
   261→	case EventTurnEnd:
   262→		// Turn end while ended is a no-op.
   263→		return TransitionResult{NewPhase: PhaseEnded}
   264→	case EventGitCommit:
   265→		if ctx.IsRebaseInProgress {
   266→			return TransitionResult{NewPhase: PhaseEnded}
   267→		}
   268→		if ctx.HasFilesTouched {
   269→			return TransitionResult{
   270→				NewPhase: PhaseEnded,
   271→				Actions:  []Action{ActionCondenseIfFilesTouched, ActionUpdateLastInteraction},
   272→			}
   273→		}
   274→		return TransitionResult{
   275→			NewPhase: PhaseEnded,
   276→			Actions:  []Action{ActionDiscardIfNoFiles, ActionUpdateLastInteraction},
   277→		}
   278→	case EventSessionStart:
   279→		return TransitionResult{
   280→			NewPhase: PhaseIdle,
   281→			Actions:  []Action{ActionClearEndedAt},
   282→		}
   283→	case EventSessionStop:
   284→		// Already ended, no-op.
   285→		return TransitionResult{NewPhase: PhaseEnded}
   286→	default:
   287→		return TransitionResult{NewPhase: PhaseEnded}
   288→	}
   289→}
