   291→// MermaidDiagram generates a Mermaid state diagram from the transition table.
   292→// The diagram is derived by calling Transition() for representative context
   293→// variants per phase/event, so it stays in sync with the implementation.
   294→func MermaidDiagram() string {
   295→	var b strings.Builder
   296→	b.WriteString("stateDiagram-v2\n")
   297→
   298→	// State declarations with descriptions.
   299→	b.WriteString("    state \"IDLE\" as idle\n")
   300→	b.WriteString("    state \"ACTIVE\" as active\n")
   301→	b.WriteString("    state \"ACTIVE_COMMITTED\" as active_committed\n")
   302→	b.WriteString("    state \"ENDED\" as ended\n")
   303→	b.WriteString("\n")
   304→
   305→	// Context variants for GitCommit: rebase, files/no-files.
   306→	type contextVariant struct {
   307→		label string
   308→		ctx   TransitionContext
   309→	}
   310→
   311→	// For each phase/event, generate edges.
   312→	for _, phase := range allPhases {
   313→		for _, event := range allEvents {
   314→			var variants []contextVariant
   315→			switch {
   316→			case event == EventGitCommit && phase == PhaseEnded:
   317→				// HasFilesTouched only affects PhaseEnded transitions;
   318→				// other phases produce identical edges for both values.
   319→				variants = []contextVariant{
   320→					{"[files]", TransitionContext{HasFilesTouched: true}},
   321→					{"[no files]", TransitionContext{HasFilesTouched: false}},
   322→					{"[rebase]", TransitionContext{IsRebaseInProgress: true}},
   323→				}
   324→			case event == EventGitCommit:
   325→				variants = []contextVariant{
   326→					{"", TransitionContext{}},
   327→					{"[rebase]", TransitionContext{IsRebaseInProgress: true}},
   328→				}
   329→			default:
   330→				variants = []contextVariant{
   331→					{"", TransitionContext{}},
   332→				}
   333→			}
   334→
   335→			for _, v := range variants {
   336→				result := Transition(phase, event, v.ctx)
   337→
   338→				// Build edge label.
   339→				label := event.String()
   340→				if v.label != "" {
   341→					label += " " + v.label
   342→				}
   343→				if len(result.Actions) > 0 {
   344→					actionNames := make([]string, 0, len(result.Actions))
   345→					for _, a := range result.Actions {
   346→						actionNames = append(actionNames, a.String())
   347→					}
   348→					label += " / " + strings.Join(actionNames, ", ")
   349→				}
   350→
   351→				from := string(phase)
   352→				to := string(result.NewPhase)
   353→
   354→				fmt.Fprintf(&b, "    %s --> %s : %s\n", from, to, label)
   355→			}
   356→		}
   357→	}
   358→
   359→	return b.String()
   360→}
