   289→// hookResponse represents a JSON response.
   290→// Used to control whether Agent continues processing the prompt.
   291→type hookResponse struct {
   292→	SystemMessage string `json:"systemMessage,omitempty"`
   293→}
   294→
   295→// outputHookResponse outputs a JSON response to stdout
   296→func outputHookResponse(reason string) error {
   297→	resp := hookResponse{
   298→		SystemMessage: reason,
   299→	}
   300→	if err := json.NewEncoder(os.Stdout).Encode(resp); err != nil {
   301→		return fmt.Errorf("failed to encode hook response: %w", err)
   302→	}
   303→	return nil
   304→}
